"""Keep the GitHub onboarding document aligned with the in-app guide."""

import argparse
from pathlib import Path

from perp_farming_bots.account_guide import GUIDES
from perp_farming_bots.models import PROVIDER_NAMES

DESTINATION = Path(__file__).resolve().parents[1] / "docs" / "api-setup.zh-CN.md"


def render() -> str:
    lines = [
        "# API 配置图文指南", "",
        "<!-- Generated by scripts/export_account_guide.py from account_guide.py. -->", "",
        "在本工具的“账户实例”页点击“API 配置指南”，可以边看图文边配置。连接表单里的指南会直接打开当前所选交易所。指南在新标签页打开，已填写的信息会留在原表单中。", "",
        "这里只填写交易 API 密钥，不填写主钱包私钥或助记词。创建与授权在交易所官网完成，本工具只验证并保存你提供的账户信息。", "",
        "截图为 2026-10-16 的官方未登录页面，用于说明入口；登录后的操作按文字步骤完成。点击图片可查看大图，官网界面可能更新。", "",
    ]
    for provider, guide in GUIDES.items():
        lines.extend([f"## {PROVIDER_NAMES[provider]}", "", guide.summary, ""])
        lines.extend(f"- [{label}]({url})" for label, url in guide.links)
        lines.extend(["", guide.notice, ""])
        for i, (title, text) in enumerate(guide.steps, 1):
            lines.append(f"{i}. **{title}**：{text}")
        lines.extend(["", f"![{guide.caption}](../src/perp_farming_bots/assets/api-guide/{guide.image})", "",
                      "| 本工具的字段 | 复制来源 | 填写说明 |", "| --- | --- | --- |"])
        lines.extend(f"| {label} | {source} | {hint} |" for label, source, hint in guide.fields)
        lines.extend(["", "账户昵称由你自己起。填完点击“验证并连接账户”；验证通过后才可以为该账户创建 Bot。", ""])
        for question, answer in guide.questions:
            lines.extend([f"### {question}", "", answer, ""])
        lines.extend([f"[官方 API 说明]({guide.reference})", ""])
    return "\n".join(lines)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    content = render()
    if args.check:
        if not DESTINATION.is_file() or DESTINATION.read_text() != content:
            raise SystemExit("API guide is out of date; run uv run python scripts/export_account_guide.py")
        print("In-app and Markdown API guides are aligned")
    else:
        DESTINATION.write_text(content)
